import {NextResponse} from "next/server";import {AudioCacheService} from "@/server/audio/audio-cache";import {getStorageContext} from "@/server/storage";export const runtime="nodejs";export const dynamic="force-dynamic";const service=()=>new AudioCacheService({database:getStorageContext().database});export async function GET(){return NextResponse.json(await service().info());}export async function DELETE(request:Request){if(request.headers.get("x-confirm-clear")!=="yes")return NextResponse.json({error:"CONFIRMATION_REQUIRED"},{status:400});return NextResponse.json(await service().clear());}
